    private static EnvironmentActivationExpression ActivationFor(ActivationPolicy policy) => policy switch
    {
        ActivationPolicy.Platform => EnvironmentActivationExpression.Feature("platform-config"),
        ActivationPolicy.Database => EnvironmentActivationExpression.Feature("database-config"),
        ActivationPolicy.PostgreSql => EnvironmentActivationExpression.Feature("postgresql-config"),
        ActivationPolicy.ServerDatabase => EnvironmentActivationExpression.Feature("server-database-config"),
        ActivationPolicy.Identity => EnvironmentActivationExpression.Feature("identity-config"),
        ActivationPolicy.Keycloak => EnvironmentActivationExpression.Feature("keycloak-config"),
        ActivationPolicy.ConfiguredBootstrap => EnvironmentActivationExpression.Feature("configured-bootstrap-config"),
        ActivationPolicy.LocalBootstrap => EnvironmentActivationExpression.Feature("local-bootstrap-config"),
        ActivationPolicy.AtprotoBootstrap => EnvironmentActivationExpression.Feature("atproto-bootstrap-config"),
        ActivationPolicy.Security => EnvironmentActivationExpression.Feature("security-config"),
        ActivationPolicy.Infisical => EnvironmentActivationExpression.Feature("infisical-config"),
        ActivationPolicy.Storage => EnvironmentActivationExpression.Feature("storage-config"),
        ActivationPolicy.S3Storage => EnvironmentActivationExpression.Feature("s3-storage-config"),
        ActivationPolicy.LocalStorage => EnvironmentActivationExpression.Feature("local-storage-config"),
        ActivationPolicy.Messaging => EnvironmentActivationExpression.Feature("messaging-config"),
        ActivationPolicy.Integration => EnvironmentActivationExpression.Feature("integration-config"),
        ActivationPolicy.Cerbos => EnvironmentActivationExpression.Feature("cerbos-config"),
        ActivationPolicy.Payments => EnvironmentActivationExpression.Feature("payments-config"),
        ActivationPolicy.Svix => EnvironmentActivationExpression.Feature("svix-config"),
        ActivationPolicy.Observability => EnvironmentActivationExpression.Feature("observability-config"),
        ActivationPolicy.Deployment => EnvironmentActivationExpression.Feature("deployment-config"),
        ActivationPolicy.ManagedDeployment => EnvironmentActivationExpression.All(
            EnvironmentActivationExpression.Capability("deployment"),
            EnvironmentActivationExpression.Not(EnvironmentActivationExpression.Topology("standalone"))),
        ActivationPolicy.ExternalCompose => EnvironmentActivationExpression.Feature("external-compose-config"),
        _ => throw new InvalidOperationException("catalogue-activation-policy-invalid"),
    };
}
